import { bindProjectPreviewUv } from "./project-preview-uv.mjs";
import { settleOwnedResources } from "./owned-resources.mjs";

// Direct extraction from Active Theory's WorkItemShader, preserved by Rhine Lab Art.
// Provenance and the small Hydra → Three adapter deviations are in vendor/active-theory/README.md.
const sections                         = source;
function expand(text        )         {
  return text.replace(/#require\(([^)]+)\)/g, (_, name        ) => expand(sections[name]))
    .replace(/#test Device.mobile\n[\s\S]*?#endtest/g, "")
    .replace(/#test !Device.mobile\n([\s\S]*?)#endtest/g, "$1");
}
const pane = sections["WorkItemShader.glsl"];
const uniforms = pane.split("#!UNIFORMS")[1].split("#!VARYINGS")[0];
const varyings = pane.split("#!VARYINGS")[1].split("#!SHADER: Vertex")[0];
const vertex = pane.split("#!SHADER: Vertex")[1].split("#!SHADER: Fragment")[0];
const fragment = pane.split("#!SHADER: Fragment")[1];
const header = "uniform float uPresentationLock;\nuniform float time;\nuniform vec2 resolution;\n" + uniforms + varyings;
// Preserve source bytes; remove its intentional slant/wave in every presentation state.
const presentationVertex = vertex
  .replace(/pos\.z \+= ([^;]+);/, "pos.z += ($1) * (1.0 - uPresentationLock);")
  .replace(/pos\.y -= ([^;]+);/, "pos.y -= ($1) * (1.0 - uPresentationLock);");
const vertexShader = "attribute vec2 projectUv;\nvarying vec2 vProjectUv;\n" + header + expand(presentationVertex).replace("vec3 pos = position;", "vProjectUv = projectUv;\n    vBackface = 0.0;\n    vec3 pos = position;");
function fragmentShader(capture         ) {
  return "uniform sampler2D tProjectPreview;\nuniform float uProjectPreview;\nvarying vec2 vProjectUv;\n" + header + expand(fragment)
    .replace(/#drawbuffer Color gl_FragColor = color;/, capture ? "" : `gl_FragColor = color;
#include <tonemapping_fragment>
#include <colorspace_fragment>
// Standard alpha composition on the SAME deformed glass surface.
if (vBackface < 0.5 && uProjectPreview > 0.5) {
  vec4 preview = texture2D(tProjectPreview, vProjectUv);
  gl_FragColor.rgb = mix(gl_FragColor.rgb, linearToOutputTexel(preview).rgb, preview.a);
}`)
    .replace(/#drawbuffer WorkRefraction gl_FragColor = refractionOut;/, capture ? "gl_FragColor = refractionOut;" : "");
}

async function imageTexture(url        , colorSpace                  , signal             ) {
  const response = await fetch(url, { signal });
  if (!response.ok) throw new Error(`Screen texture failed: ${url}`);
  const image = await createImageBitmap(await response.blob(), { imageOrientation: "flipY", premultiplyAlpha: "none" });
  const texture = new THREE.Texture(image);
  texture.colorSpace = colorSpace; texture.flipY = false; texture.needsUpdate = true;
  return texture;
}

function releaseTexture(texture               ) {
  if (texture.image instanceof ImageBitmap) texture.image.close();
  texture.dispose();
}

export function createActiveTheoryPane() {
  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute("position", new THREE.Float32BufferAttribute(cube.position, 3));
  geometry.setAttribute("normal", new THREE.Float32BufferAttribute(cube.normal, 3));
  geometry.setAttribute("uv", new THREE.Float32BufferAttribute(cube.uv, 2));
  geometry.computeBoundingSphere();
  bindProjectPreviewUv(geometry);
  const blank = new THREE.DataTexture(new Uint8Array([0, 0, 0, 255]), 1, 1);
  blank.needsUpdate = true;
  const flatNormal = new THREE.DataTexture(new Uint8Array([128, 128, 255, 255]), 1, 1);
  flatNormal.needsUpdate = true;
  const target = new THREE.WebGLRenderTarget(1, 1, { type: THREE.HalfFloatType });
  const shared = {
    uPresentationLock: { value: 1 }, time: { value: 0 }, resolution: { value: new THREE.Vector2(1, 1) },
    tMap: { value: blank }, tVideo: { value: blank }, tRefraction: { value: target.texture },
    tEnv: { value: blank                  }, tNormal: { value: flatNormal                  },
    uFresnelPow: { value: 1 }, uDistortStrength: { value: 0 }, uRefractionRatio: { value: 1 },
    uColor: { value: new THREE.Color(0) }, uHover: { value: 0 },
    uMouse: { value: new THREE.Vector2(.5, .5) }, uVideoBlend: { value: 0 },
    uScale: { value: new THREE.Vector2(1, 1) }, uPhone: { value: 0 },
  };
  const materials                         = [];
  function createMaterial() {
    const material = new THREE.ShaderMaterial({
      uniforms: { ...shared, tProjectPreview: { value: blank                  }, uProjectPreview: { value: 0 } },
      vertexShader, fragmentShader: fragmentShader(false),
    });
    materials.push(material); return material;
  }
  const captureMaterial = new THREE.ShaderMaterial({ uniforms: shared, vertexShader, fragmentShader: fragmentShader(true), transparent: true });
  const size = new THREE.Vector2();
  let disposed = false;
  const loading = new AbortController();
  const assetsReady = settleOwnedResources([
    imageTexture(new URL("./waternormals.jpg", import.meta.url).href, THREE.NoColorSpace, loading.signal),
    imageTexture(new URL("./env1.jpg", import.meta.url).href, THREE.SRGBColorSpace, loading.signal),
  ], releaseTexture, () => disposed).then(textures => {
    if (!textures) return;
    const [normal, env] = textures;
    normal.wrapS = normal.wrapT = THREE.RepeatWrapping;
    shared.tNormal.value = normal; shared.tEnv.value = env;
  });
  // The model boot awaits this original promise; handle early rejection until it does.
  void assetsReady.catch(() => {});
  return {
    geometry, createMaterial, captureMaterial, assetsReady,
    // Keep the original 4 × 2.6 × 1 source transform and normalize its 3.0386-unit width.
    scale: new THREE.Vector3(4, 2.6, 1).divideScalar(.7596493946 * 4),
    update(dt        , reducedMotion         ) { if (!reducedMotion) shared.time.value += dt; },
    capture(renderer                     , scene             , camera              , meshes              ) {
      if (!meshes.some(mesh => mesh.parent?.visible)) return;
      renderer.getDrawingBufferSize(size);
      if (size.x !== target.width || size.y !== target.height) target.setSize(size.x, size.y);
      shared.resolution.value.copy(size);
      const previous = renderer.getRenderTarget();
      const previousMaterials = meshes.map(mesh => mesh.material);
      try {
        // The reference uses a distinct WorkRefraction layer/snapshot. This pass writes
        // its refractionOut attachment; only the subsequent main pass samples it.
        shared.tRefraction.value = blank;
        for (const mesh of meshes) mesh.material = captureMaterial;
        renderer.setRenderTarget(target); renderer.render(scene, camera);
      } finally {
        shared.tRefraction.value = target.texture;
        meshes.forEach((mesh, index) => { mesh.material = previousMaterials[index]; });
        renderer.setRenderTarget(previous);
      }
    },
    dispose() {
      disposed = true; loading.abort();
      geometry.dispose(); materials.forEach(material => material.dispose()); captureMaterial.dispose(); target.dispose();
      for (const texture of new Set([blank, flatNormal, shared.tNormal.value, shared.tEnv.value])) {
        releaseTexture(texture);
      }
    },
  };
}
